using System;using System.IO;using System.Linq;using System.Reflection;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Automation;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Media.Media3D;using System.Windows.Threading;using RingTimer;
class SilverCardTests {
 static int checks;
 [DllImport("gdi32.dll")]static extern IntPtr CreateRectRgn(int l,int t,int r,int b);
 [DllImport("user32.dll")]static extern int GetWindowRgn(IntPtr window,IntPtr region);
 [DllImport("gdi32.dll")]static extern bool PtInRegion(IntPtr region,int x,int y);
 [DllImport("gdi32.dll")]static extern bool DeleteObject(IntPtr region);
 static bool NativeContains(MenuWindow menu,Point point){IntPtr r=CreateRectRgn(0,0,0,0);try{GetWindowRgn(menu.Handle,r);double dpi=Native.ScaleFor(menu.Handle);return PtInRegion(r,(int)(point.X*dpi),(int)(point.Y*dpi));}finally{DeleteObject(r);}}
 static byte AlphaAt(MenuWindow menu,int x,int y){var bitmap=new RenderTargetBitmap((int)Math.Ceiling(menu.ActualWidth),(int)Math.Ceiling(menu.ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(menu);byte[] pixel=new byte[4];bitmap.CopyPixels(new Int32Rect(x,y,1,1),pixel,4,0);return pixel[3];}
 static void SilverOnly(){foreach(bool dark in new[]{true,false}){Theme.Apply(dark,null,null,null);var film=new SilverCardFilm();film.Measure(new Size(352,610));film.Arrange(new Rect(0,0,352,610));film.SetPose(10,-8,1);var bitmap=new RenderTargetBitmap(352,610,96,96,PixelFormats.Pbgra32);bitmap.Render(film);byte[] pixels=new byte[352*610*4];bitmap.CopyPixels(pixels,352*4,0);bool neutral=true;for(int i=0;i<pixels.Length;i+=4)if(pixels[i]!=pixels[i+1]||pixels[i+1]!=pixels[i+2]){neutral=false;break;}Check(neutral,"reflection material contains only neutral silver values "+dark);}}
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
 static void Pump(int ms=100){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
 static IEnumerable<T> All<T>(DependencyObject n) where T:DependencyObject{if(n is T)yield return (T)n;for(int i=0;i<VisualTreeHelper.GetChildrenCount(n);i++)foreach(var v in All<T>(VisualTreeHelper.GetChild(n,i)))yield return v;}
 static void PoseTests(){foreach(var size in new[]{new Size(368,400),new Size(368,642),new Size(368,320),new Size(460,800)}){
   var flat=new CardProjection(size,0,0);Check((flat.Project(new Point(8,8))-new Point(8,8)).Length<.001,"identity projection "+size);
   foreach(double x in new[]{-12.0,0,12.0})foreach(double y in new[]{-12.0,0,12.0}){var p=new CardProjection(size,x,y);Check(p.Outline(new Rect(8,8,size.Width-16,size.Height-16),34).All(pt=>pt.X>=0&&pt.X<=size.Width&&pt.Y>=0&&pt.Y<=size.Height),"projected contour fits "+size+" "+x+" "+y);}
 }var clamped=new CardProjection(new Size(368,642),900,-900);Check(clamped.Pitch==12&&clamped.Yaw==-12,"angles bounded");Check(Math.Abs(clamped.Project(new Point(8,8)).Y-clamped.Project(new Point(360,8)).Y)>1,"perspective tilts top edge");}
 [STAThread]static int Main(string[] args){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};MenuWindow menu=null;var prefs=new AppearanceSettings(null);try{
 PoseTests();SilverOnly();Theme.Apply(true,null,null,null);var now=DateTime.UtcNow;var engine=new TimerEngine(new TimerState(),()=>now);var timer=new TimerFeature(engine,()=>{});var stats=new StatsFeature(new StatsStore(null));var context=new ContextFeature();
 menu=new MenuWindow(new FeatureRegistry(timer,stats,context),()=>{},()=>{},prefs){AnimationsEnabled=false,Left=-2200,Top=0};menu.OpenFeature("timer");menu.Reveal();Pump();
 var presenter=menu.CardPresenter;var readout=All<TextBlock>(timer.Panel).Single(t=>AutomationProperties.GetName(t)=="剩余时间");var count=All<TextBox>(timer.Panel).Single();var surface=menu.CardSurface;
 Check(!presenter.FrameSubscribed,"no idle animation callback");Theme.Snapshot(menu,Path.Combine(args[0],"dark-rest.png"),1.5);
 engine.StartCycle(60,15,1);timer.Refresh();string before=readout.Text;long deadline=engine.State.Deadline;
 presenter.Begin(new Point(180,250));presenter.Move(new Point(350,60));Pump(450);
 Check(presenter.IsPresenting&&presenter.IsHeld&&presenter.Yaw>5&&presenter.Pitch>3,"entire card tilts while held");Check(All<Viewport2DVisual3D>(presenter).First(v=>Object.ReferenceEquals(v.Visual,presenter.ContentVisual)).Visual!=null,"live WPF card hosted in perspective");
 var live=(FrameworkElement)All<Viewport2DVisual3D>(presenter).First(v=>Object.ReferenceEquals(v.Visual,presenter.ContentVisual)).Visual;var sample=new Point(45,120);Check((live.TranslatePoint(sample,presenter)-presenter.Projection.Project(sample)).Length<.5,"rendered perspective matches native contour math actual="+live.TranslatePoint(sample,presenter)+" expected="+presenter.Projection.Project(sample)+" liveSize="+live.RenderSize+" viewport="+presenter.RenderSize);
 Check(NativeContains(menu,new Point(menu.ActualWidth/2,menu.ActualHeight/2))&&!NativeContains(menu,new Point(9,9)),"native region follows projected card");
 var nativeBounds=menu.PixelBounds;double dpiScale=Native.ScaleFor(menu.Handle);menu.AnchorBounds=()=>new Native.RECT{Left=nativeBounds.Left+(int)(160*dpiScale),Top=nativeBounds.Top+(int)(280*dpiScale),Right=nativeBounds.Left+(int)(204*dpiScale),Bottom=nativeBounds.Top+(int)(324*dpiScale)};presenter.UpdateContour();Check(!NativeContains(menu,new Point(182,302)),"launcher cutout stays at independent screen anchor");menu.AnchorBounds=null;presenter.UpdateContour();
 now=now.AddSeconds(5);engine.Tick();menu.Refresh();Pump();Check(readout.Text!=before&&engine.State.Deadline==deadline,"countdown updates live while held");Check(presenter.IsPresenting,"ordinary timer refresh preserves held card");
 Theme.Snapshot(menu,Path.Combine(args[0],"dark-tilt.png"),1.5);presenter.Release();Pump();Check(!presenter.IsPresenting&&!presenter.FrameSubscribed,"reduced-animation release returns immediately");
 Check(All<TextBox>(timer.Panel).Single()==count&&menu.CardSurface==surface,"return preserves original controls");
 menu.AnimationsEnabled=true;presenter.Begin(new Point(180,250));presenter.Move(new Point(-500,900));Pump(400);double initial=Math.Abs(presenter.Yaw);presenter.Release();Pump(90);Check(presenter.IsPresenting&&Math.Abs(presenter.Yaw)<initial,"animated return moves toward rest");Pump(500);Check(!presenter.IsPresenting&&!presenter.FrameSubscribed,"animated return ends and removes callback");
 presenter.Begin(new Point(180,250));presenter.RaiseEvent(new MouseEventArgs(Mouse.PrimaryDevice,0){RoutedEvent=Mouse.LostMouseCaptureEvent});Pump(450);Check(!presenter.IsPresenting,"capture loss returns safely");
 presenter.Begin(new Point(180,250));menu.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(menu),0,Key.Escape){RoutedEvent=Keyboard.PreviewKeyDownEvent});Pump(450);Check(!presenter.IsPresenting&&menu.IsVisible,"Escape restores card without closing menu");
 presenter.Begin(new Point(180,250));menu.OpenSettings();Pump(450);Check(!presenter.IsPresenting&&menu.ActiveId=="settings","navigation restores normal card before page change");
 menu.AnimationsEnabled=false;menu.OpenFeature("timer");engine.StopCycle();timer.Refresh();timer.Panel.OpenEditor("work");Pump();Check(timer.Panel.IsEditing,"duration editor is open before gesture");presenter.Begin(new Point(180,250));presenter.Move(new Point(330,80));Pump(300);presenter.Release();Pump();Check(timer.Panel.IsEditing,"duration editor survives card gesture");timer.Panel.CancelEditor();
 presenter.Begin(new Point(180,250));menu.OpenFeature("stats");Pump();Check(!presenter.IsPresenting&&menu.ActiveId=="stats","same-sized feature navigation restores normal card");
 menu.OpenFeature("timer");menu.AnimationsEnabled=true;menu.Activate();count.Focus();Pump();presenter.Begin(new Point(180,250));presenter.Move(new Point(330,80));Pump(200);
 var other=new Window{Title="Silver card focus test",Width=120,Height=80,Left=-2500,Top=0,ShowInTaskbar=false};try{other.Show();other.Activate();Pump(600);Check(other.IsActive&&!menu.IsActive&&!presenter.IsPresenting,"switching windows keeps keyboard focus in the new window after return");}finally{other.Close();}
 menu.AnimationsEnabled=false;
 foreach(bool dark in new[]{false,true}){Theme.Apply(dark,null,null,null);foreach(int alpha in new[]{0,42,90}){prefs.Transparency=alpha;menu.ShowHome();Pump();Theme.Snapshot(menu,Path.Combine(args[0],(dark?"dark":"light")+"-home-"+alpha+".png"),1.5);presenter.Begin(new Point(180,200));presenter.Move(new Point(320,60));Pump(400);Theme.Snapshot(menu,Path.Combine(args[0],(dark?"dark":"light")+"-held-"+alpha+".png"),1.5);presenter.Release();Pump();Check(!presenter.IsPresenting&&!presenter.FrameSubscribed,"theme and transparency gesture round trip "+dark+" "+alpha);}}
 presenter.Begin(new Point(180,250));menu.HideImmediately();Pump();Check(!presenter.IsPresenting&&!presenter.IsMouseCaptured&&!presenter.FrameSubscribed,"hide tears down pose and capture");
 menu.AnimationsEnabled=true;menu.Reveal();menu.UpdateLayout();Check(AlphaAt(menu,(int)menu.ActualWidth/2,(int)menu.ActualHeight/2)==0,"silver film follows opening contour before card is revealed");Pump(400);Check(AlphaAt(menu,(int)menu.ActualWidth/2,(int)menu.ActualHeight/2)>0,"opening completes with visible card material");
 presenter.Begin(new Point(180,250));presenter.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice,0,MouseButton.Right){RoutedEvent=UIElement.PreviewMouseRightButtonUpEvent});Pump(400);Check(!presenter.IsPresenting,"right-button release event restores card");
 presenter.Begin(new Point(180,250));menu.ClosePanel();Pump(400);Check(!menu.IsVisible&&!presenter.IsPresenting&&!presenter.FrameSubscribed,"close during tilt restores and hides card");
 Console.WriteLine(checks+" silver card checks passed");return 0;
 }catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}finally{if(menu!=null){menu.Disposing=true;menu.Close();}prefs.Dispose();app.Shutdown();}}
}
